export const origins={embryo:{name:'Human embryo',targets:['nerve','muscle','blood'],scope:'Most human cell types'},marrow:{name:'Adult bone marrow',targets:['blood'],scope:'A limited range, including blood cells'},meristem:{name:'Plant meristem',targets:['root','xylem','leaf'],scope:'Any plant cell type throughout life'}};
export const targetNames={nerve:'Nerve cell',muscle:'Muscle cell',blood:'Blood cell',root:'Root hair cell',xylem:'Xylem cell',leaf:'Leaf cell'};
export const canDifferentiate=(origin,target)=>Boolean(origins[origin]?.targets.includes(target));
export const lineageTasks=[{origin:'embryo',target:'nerve',answer:'most',prompt:'Can this source supply different human cell types?',options:[['most','Most human cell types'],['blood','Blood cells only'],['plant','Only plant cells']]},{origin:'marrow',target:'nerve',answer:'limited',prompt:'Can adult bone marrow be assumed to supply every human cell type?',options:[['all','Yes, every adult stem cell can make any cell'],['limited','No, its possible outcomes are more restricted'],['none','No, it cannot form blood cells']]},{origin:'meristem',target:'root',answer:'life',prompt:'When can meristem cells produce new specialised plant cells?',options:[['early','Only before the seed germinates'],['life','Throughout the plant’s life'],['never','Never: plant cells cannot differentiate']]}];
export function lineageComplete(w,t){return w.predictions?.[t.origin]===t.answer&&w.renewed?.[t.origin]&&w.explored?.includes(t.origin+':'+t.target)&&w.explored?.includes(t.origin+':'+(t.origin==='marrow'?'blood':t.origin==='embryo'?'muscle':'xylem'));}
export const useTasks=[{id:'therapy',title:'Potential treatment',prompt:'Compare replacement-cell proposals for diabetes and paralysis. A matching cell role matters; the diagram is not a prediction of clinical success.',choices:[['insulin','Insulin-producing cells for diabetes'],['nerve','Nerve cells for paralysis']],answer:'potential',options:[['certain','These diagrams prove both conditions can always be cured'],['potential','Potential; evidence needed'],['unrelated','Cell function is irrelevant to treatment']]},{id:'cloning',title:'Match the genes; keep the risks',prompt:'Switch between an unrelated source and a therapeutic-cloning source with the patient’s genes. Separately investigate viral contamination.',choices:[['unrelated','Unrelated source'],['matched','Patient-matched embryo']],answer:'both',options:[['none','Matching genes removes every treatment risk'],['both','Match ≠ infection protection'],['virus','Matching genes guarantees viral infection']]},{id:'plants',title:'Clone a useful plant',prompt:'Compare meristem clones of a rare plant and a disease-resistant crop. Cloning preserves a selected genetic combination; it does not create a new resistance gene.',choices:[['rare','Rare species'],['crop','Disease-resistant crop']],answer:'balance',options:[['balance','Useful copies; shared risks'],['new','Cloning automatically creates new resistance genes'],['all','A single clone guarantees that extinction can never happen']]}];
export function useComplete(w,t){return t.choices.every(([key])=>w.seenUses?.includes(t.id+':'+key))&&w.useAnswers?.[t.id]===t.answer&&(t.id!=='cloning'||w.risksSeen?.includes('clean')&&w.risksSeen?.includes('virus'));}
